132	
133	        if (newline == std::string_view::npos) break;
134	        start = newline + 1;
135	    }
136	    if (state != State::AfterMarker) return false;
137	
138	    std::vector<unsigned char> decoded;
139	    return base64_decode(base64, decoded) && decoded == der;
