216	bool format_name(X509_NAME* name, std::string& out) {
217	    int count = X509_NAME_entry_count(name);
218	    int previous_set = -1;
219	    for (int i = 0; i < count; ++i) {
220	        X509_NAME_ENTRY* entry = X509_NAME_get_entry(name, i);
221	        if (entry == nullptr) return false;
222	        ASN1_OBJECT* object = X509_NAME_ENTRY_get_object(entry);
223	        ASN1_STRING* asn1_value = X509_NAME_ENTRY_get_data(entry);
224	        if (object == nullptr || asn1_value == nullptr) return false;
225	
226	        const char* short_name = nullptr;
227	        char oid_buffer[80];
228	        int nid = OBJ_obj2nid(object);
229	        if (nid != NID_undef) short_name = OBJ_nid2sn(nid);
230	        if (short_name == nullptr) {
231	            if (OBJ_obj2txt(oid_buffer, sizeof(oid_buffer), object, 1) <= 0) {
232	                return false;
233	            }
234	            short_name = oid_buffer;
235	        }
236	
237	        unsigned char* utf8_raw = nullptr;
238	        int utf8_length = ASN1_STRING_to_UTF8(&utf8_raw, asn1_value);
239	        if (utf8_length < 0) return false;
240	        std::unique_ptr<unsigned char, OpenSSLFree> utf8_guard(
241	            utf8_raw, OpenSSLFree{});
242	        std::string value(reinterpret_cast<char*>(utf8_raw),
243	                          static_cast<size_t>(utf8_length));
244	        if (!is_valid_utf8(value)) value = latin1_to_utf8(value);
245	
246	        int current_set = X509_NAME_ENTRY_set(entry);
247	        if (i > 0) {
248	            out.append(current_set == previous_set ? "+" : ", ");
249	        }
250	        out.append(short_name);
251	        out.push_back('=');
252	        out.append(escape_dn_value(value));
253	        previous_set = current_set;
254	    }
255	    return true;
256	}
