295	int inspect_file(const std::string& path) {
296	    std::ifstream stream(path, std::ios::binary);
297	    if (!stream) {
298	        std::cerr << "trustpeek: failed to read file '" << path
299	                  << "': " << std::strerror(errno) << '\n';
300	        return 1;
301	    }
302	    std::ostringstream contents;
303	    contents << stream.rdbuf();
304	    if (stream.bad()) {
305	        std::cerr << "trustpeek: failed to read file '" << path
306	                  << "': " << std::strerror(errno) << '\n';
307	        return 1;
308	    }
309	    std::string content = contents.str();
310	
311	    if (content.empty()) {
312	        std::cerr << "trustpeek: invalid certificate in '" << path
313	                  << "': empty file\n";
314	        return 1;
315	    }
316	
317	    const bool looks_like_pem =
318	        content.find(kPemBegin) != std::string::npos;
319	    const char* encoding_name = looks_like_pem ? "PEM" : "DER";
320	
321	    X509Ptr cert(nullptr, X509_free);
322	
323	    if (looks_like_pem) {
324	        BioPtr bio(BIO_new_mem_buf(content.data(),
325	                                  static_cast<int>(content.size())),
326	                   BIO_free_all);
327	        if (!bio) {
328	            std::cerr << "trustpeek: internal error while reading '" << path
329	                      << "'\n";
330	            return 1;
331	        }
332	        cert.reset(PEM_read_bio_X509(bio.get(), nullptr, nullptr, nullptr));
333	        if (!cert) {
334	            std::cerr << "trustpeek: invalid certificate in '" << path
335	                      << "': PEM certificate block is malformed or truncated\n";
336	            return 1;
337	        }
338	    } else {
339	        const auto* pointer =
340	            reinterpret_cast<const unsigned char*>(content.data());
341	        cert.reset(d2i_X509(nullptr, &pointer,
342	                            static_cast<long>(content.size())));
343	        if (!cert) {
344	            std::cerr << "trustpeek: invalid certificate in '" << path
345	                      << "': DER certificate is malformed or truncated\n";
346	            return 1;
347	        }
348	        if (pointer != reinterpret_cast<const unsigned char*>(
349	                            content.data() + content.size())) {
350	            std::cerr << "trustpeek: invalid certificate in '" << path
351	                      << "': trailing bytes after DER certificate\n";
352	            return 1;
353	        }
354	    }
355	
356	    std::vector<unsigned char> der;
357	    if (!encode_to_der(cert.get(), der)) {
358	        std::cerr << "trustpeek: invalid certificate in '" << path
359	                  << "': failed to re-encode certificate\n";
360	        return 1;
361	    }
362	
363	    if (looks_like_pem && !validate_single_pem(content, der)) {
364	        std::cerr << "trustpeek: invalid certificate in '" << path
365	                  << "': expected exactly one PEM certificate block with no "
366	                     "other non-whitespace content\n";
367	        return 1;
368	    }
369	
370	    std::string subject;
371	    std::string issuer;
372	    std::string not_before;
373	    std::string not_after;
374	    if (!format_name(X509_get_subject_name(cert.get()), subject) ||
375	        !format_name(X509_get_issuer_name(cert.get()), issuer) ||
376	        !format_time(X509_get0_notBefore(cert.get()), not_before) ||
377	        !format_time(X509_get0_notAfter(cert.get()), not_after)) {
378	        std::cerr << "trustpeek: invalid certificate in '" << path
379	                  << "': failed to parse certificate fields\n";
380	        return 1;
381	    }
382	
383	    unsigned char digest[EVP_MAX_MD_SIZE];
384	    size_t digest_length = 0;
385	    if (EVP_Q_digest(nullptr, "SHA256", nullptr, der.data(), der.size(), digest,
386	                     &digest_length) != 1) {
387	        std::cerr << "trustpeek: internal error while hashing '" << path
388	                  << "'\n";
389	        return 1;
390	    }
391	
392	    std::ostringstream output;
393	    output << "Encoding: " << encoding_name << '\n'
394	           << "Subject: " << subject << '\n'
395	           << "Issuer: " << issuer << '\n'
396	           << "Not Before: " << not_before << '\n'
397	           << "Not After: " << not_after << '\n'
398	           << "SHA-256 Fingerprint: "
399	           << format_fingerprint(digest, digest_length) << '\n'
400	           << "Note: this output displays certificate information only; "
401	              "reading the file successfully does not verify the signature "
402	              "or establish trust.\n";
403	    std::cout << output.str();
404	    return 0;
405	}
